1	import 'package:flutter/material.dart';
2	
3	import '../design_tokens.dart';
4	
5	/// The three button variants named in prototype-extract.md §6's component
6	/// table: primary (filled), secondary (outline), text (ghost).
7	enum AppButtonVariant { primary, secondaryOutline, textGhost }
8	
9	/// Shared button primitive consumed by every feature's `presentation/`
10	/// (Story 1.3 login/signup, Story 1.5 overlay, Story 1.6 nav shell).
11	///
12	/// Disabled state is identical across all three variants, per the
13	/// project-wide rule: `colorBorder` background + `colorTextSecondary`
14	/// text, never a dimmed-opacity look.
15	class AppButton extends StatelessWidget {
16	  const AppButton({
17	    super.key,
18	    required this.label,
19	    required this.onPressed,
20	    this.variant = AppButtonVariant.primary,
21	    this.textColor,
22	  });
23	
24	  /// Button label. Rendered with no `maxLines`/`overflow` clamp so it
25	  /// wraps rather than clips or truncates under Dynamic Type.
26	  final String label;
27	
28	  /// Null disables the button and switches it to the disabled visual
29	  /// state (see class doc).
30	  final VoidCallback? onPressed;
31	
32	  final AppButtonVariant variant;
33	
34	  /// Only consulted for [AppButtonVariant.textGhost]: the component table
35	  /// allows ghost buttons to use either `colorPrimary` or
36	  /// `colorTextSecondary` depending on context (e.g. "Fechar"/"Limpar").
37	  /// Defaults to `colorPrimary`.
38	  final Color? textColor;
39	
40	  @override
41	  Widget build(BuildContext context) {
42	    final Widget child = Text(label, textAlign: TextAlign.center, style: DesignTokens.textLabelMd);
43	
44	    final ButtonStyle baseStyle = ButtonStyle(
45	      padding: const WidgetStatePropertyAll(DesignTokens.buttonPadding),
46	      shape: const WidgetStatePropertyAll(
47	        RoundedRectangleBorder(
48	          borderRadius: BorderRadius.all(Radius.circular(DesignTokens.radiusSm)),
49	        ),
50	      ),
51	      elevation: const WidgetStatePropertyAll(0),
52	    );
53	
54	    switch (variant) {
55	      case AppButtonVariant.primary:
56	        return ElevatedButton(
57	          onPressed: onPressed,
58	          style: baseStyle.copyWith(
59	            backgroundColor: WidgetStateProperty.resolveWith((states) {
60	              if (states.contains(WidgetState.disabled)) {
61	                return DesignTokens.colorBorder;
62	              }
63	              return DesignTokens.colorPrimary;
64	            }),
65	            foregroundColor: WidgetStateProperty.resolveWith((states) {
66	              if (states.contains(WidgetState.disabled)) {
67	                return DesignTokens.colorTextSecondary;
68	              }
69	              return DesignTokens.colorOnPrimary;
70	            }),
71	            overlayColor: WidgetStateProperty.resolveWith((states) {
72	              if (states.contains(WidgetState.pressed)) {
73	                return DesignTokens.colorPrimaryPressed;
74	              }
75	              return Colors.transparent;
76	            }),
77	          ),
78	          child: child,
79	        );
80	
81	      case AppButtonVariant.secondaryOutline:
82	        return OutlinedButton(
83	          onPressed: onPressed,
84	          style: baseStyle.copyWith(
85	            backgroundColor: WidgetStateProperty.resolveWith((states) {
86	              if (states.contains(WidgetState.disabled)) {
87	                return DesignTokens.colorBorder;
88	              }
89	              return Colors.transparent;
90	            }),
91	            foregroundColor: WidgetStateProperty.resolveWith((states) {
92	              if (states.contains(WidgetState.disabled)) {
93	                return DesignTokens.colorTextSecondary;
94	              }
95	              return DesignTokens.colorPrimary;
96	            }),
97	            side: WidgetStateProperty.resolveWith((states) {
98	              if (states.contains(WidgetState.disabled)) {
99	                return const BorderSide(color: DesignTokens.colorBorder);
100	              }
101	              return const BorderSide(color: DesignTokens.colorPrimary);
102	            }),
103	          ),
104	          child: child,
105	        );
106	
107	      case AppButtonVariant.textGhost:
108	        return TextButton(
109	          onPressed: onPressed,
110	          style: baseStyle.copyWith(
111	            backgroundColor: WidgetStateProperty.resolveWith((states) {
112	              if (states.contains(WidgetState.disabled)) {
113	                return DesignTokens.colorBorder;
114	              }
115	              return Colors.transparent;
116	            }),
117	            foregroundColor: WidgetStateProperty.resolveWith((states) {
118	              if (states.contains(WidgetState.disabled)) {
119	                return DesignTokens.colorTextSecondary;
120	              }
121	              return textColor ?? DesignTokens.colorPrimary;
122	            }),
123	          ),
124	          child: child,
125	        );
126	    }
127	  }
128	}
